def experiment(inputs):
    import random
    seeds = inputs.get('seeds', [42, 42, 42])
    results = []
    for s in seeds:
        random.seed(s)
        results.append(random.random())
    divergence = 0.0 if len(set(results)) == 1 else 1.0
